A: You can use the following code:


const readline = require('readline').createInterface({
  input: process.stdin,
  output: process.stdout
});

readline.question('Are you positive for COVID-19?', (response) => {
  if (response === 'positive') {
    console.log('I am positive for COVID-19!');
  } else if (response === 'negative') {
    console.log('I am negative for COVID-19!');
  } else {
    console.log('Please input a valid response.');
  }
});


This code will ask you to input a valid response, and it will check if you provided a positive or negative response.

